import { sprintf }				from 'sprintf-js';
import { AccCatId, type AccConfig, type AccService, type SrvCharacteristic, type GeneratorContext, type GeneratorResult } from '../lib/types';
import { constChar, onlyAck, sortBy } from '../lib/helpers';


// ~~~~~~~~~
// FRITZ_MAP
// ~~~~~~~~~
// accessory generated by createFritzdect() for a productname; 'Name' is added last
//		TargetHeatingCoolingState:	0 := OFF, 1 := HEAT, 2 := COOL, 3 := AUTO
//		CurrentHeatingCoolingState:	0 := OFF, 1 := HEAT, 2 := COOL
const FRITZ_MAP: Record<string, { category: string, type: string, characteristics: (id: string) => SrvCharacteristic[], historyIds: string[] }> = {
	'FRITZ!DECT Repeater 100': {
		category: AccCatId.Sensor,
		type: 'TemperatureSensor',
		characteristics: id => [
			onlyAck('CurrentTemperature', `${id}.celsius`),
		],
		historyIds: [ 'celsius' ],
	},
	'FRITZ!Smart Energy 200': {
		category: AccCatId.Switch,
		type: 'Switch',
		characteristics: id => [
			onlyAck('On', `${id}.state`),
		],
		historyIds: [ 'state' ],
	},
	'FRITZ!Smart Thermo 301': {
		category: AccCatId.Thermostat,
		type: 'Thermostat',
		characteristics: id => [
			constChar('TemperatureDisplayUnits',	0),
			onlyAck  ('TargetTemperature',			`${id}.tsoll`),
			onlyAck  ('CurrentTemperature',			`${id}.tist`),
			constChar('TargetHeatingCoolingState',	3),
			onlyAck  ('CurrentHeatingCoolingState',	`${id}.heatingCoolingState`),
		],
		historyIds: [ 'tsoll', 'tist' ],
	},
};


// createFritzdect: one accessory per fritzdect channel, mapped by its 'productname' (see FRITZ_MAP);
// channels of unknown products are logged as errors and skipped
export async function createFritzdect({ adapter, srcInstId }: GeneratorContext): Promise<GeneratorResult> {
	const accConfigs: AccConfig[] = [];
	const historyIds: string[] = [];

	// fritzdect channels
	const channels = await adapter.getForeignObjectsAsync(`${srcInstId}.*`, 'channel');
	for (const channel of Object.values(channels).sort(sortBy('_id'))) {
		const productname = await adapter.getForeignStateAsync(`${channel._id}.productname`);
		if (productname) {
			const productName = String(productname.val);
			const product = Object.hasOwn(FRITZ_MAP, productName) ? FRITZ_MAP[productName] : undefined;
			if (! product) {
				adapter.log.error(sprintf('%-31s %-20s %-50s %s', 'createFritzdect()', 'unknown', 'productname', productName));
			} else {
				const characteristics = product.characteristics(channel._id);
				for (const historyId of product.historyIds) {
					historyIds.push(`${channel._id}.${historyId}`);
				}

				const idPath	= channel._id.split('.');						// [ 'fritzdect', '0', 'DECT_099950049519' ]
				const group	= idPath.slice(0, 2).join('.');
				const [ nameObj, manufacturer, fwVersion ] = await Promise.all([
					adapter.getForeignStateAsync(`${channel._id}.name`),
					adapter.getForeignStateAsync(`${channel._id}.manufacturer`),
					adapter.getForeignStateAsync(`${channel._id}.fwversion`),
				]);
				const devName	= (typeof nameObj?.val === 'string') ? nameObj.val : 'unknown';

				// add Name characteristic
				characteristics.push(constChar('Name', devName));

				// accConfig
				const accConfig: AccConfig = {
					'category':			product.category,
					'groupString':		group,									// used by adapter only
					'name':				channel._id,							// NOTE: yahka adapter uses 'name' to build homekit UUID!
					'manufacturer':		String(manufacturer?.val ?? 'n/a'),		// visible within iOS home app
					'model':			devName,								// visible within iOS home app
					'firmware':			String(fwVersion?.val ?? 'n/a'),		// visible within iOS home app
					'serial':			idPath[2] ?? '',						// visible within iOS home app
					'services':			[],
				};
				accConfigs.push(accConfig);

				// accService
				const accService: AccService = {
					'type': product.type,
					'subType': '',
					'name': devName,
					'characteristics': characteristics
				};
				accConfig.services.push(accService);
				adapter.log.debug(sprintf('%-31s %-20s %-50s %s', 'createFritzdect()', accService.type, accConfig.name, accService.name));
			}
		}
	}

	return { devices: accConfigs, invalid: [], historyIds };
}
